for(let i=-.25;i<=.25;i+=.05){ chip.add(mesh(new THREE.BoxGeometry(.02,.012,.04),M(0xd4a640,.2,1),i,-.03,.29,false)); chip.add(mesh(new THREE.BoxGeometry(.02,.012,.04),M(0xd4a640,.2,1),i,-.03,-.29,false)); }
chip.position.set(0,1.35,0); chip.rotation.x=-.35; scene.add(chip);
for(let i=0;i<6;i++){ const a=i/6*Math.PI*2; scene.add(mesh(new THREE.CylinderGeometry(.04,.06,.95,10),M(0xb08a3e,.3,.9),Math.cos(a)*2.2,.48,Math.sin(a)*2.2)); }
for(let i=0;i<6;i++){ const a=i/6*Math.PI*2, b=(i+1)/6*Math.PI*2; const p1=new THREE.Vector3(Math.cos(a)*2.2,.85,Math.sin(a)*2.2), p2=new THREE.Vector3(Math.cos(b)*2.2,.85,Math.sin(b)*2.2), mid=p1.clone().add(p2).multiplyScalar(.5); mid.y=.68;
  const curve=new THREE.QuadraticBezierCurve3(p1,mid,p2); scene.add(mesh(new THREE.TubeGeometry(curve,12,.025,6),M(0x7a1424,.6),0,0,0,false)); }

// lights
