  if(o.outfit==="gown"||o.outfit==="qipao") add(body,G.gown,M(o.top,o.outfit==="qipao"?.35:.6,o.outfit==="qipao"?.15:0,{side:THREE.DoubleSide}),0,.5,0,o.outfit==="qipao"?.82:1,1,o.outfit==="qipao"?.75:.85);
  if(o.outfit==="qipao"){ add(body,G.collar,M(o.top,.35,.15,{side:THREE.DoubleSide}),0,1.6,0); const tr=add(body,new THREE.BoxGeometry(.13,.012,.012),M(0xd4a640,.25,.9),.035,1.45,.13); tr.rotation.z=.55; [1.38,1.31].forEach(y=>add(body,new THREE.BoxGeometry(.03,.012,.012),M(0xd4a640,.25,.9),.075,y,.132)); }
