  add(body,G.mouth,M(o.fem?(o.lip||0xa83a48):0x8a4a3e,o.fem?.35:.6),0,1.675,.128,o.fem?1.1:1,o.fem?1.5:1,1);
  if(o.fem){ [-.045,.045].forEach(x=>add(body,G.lash,M(0x0b0806,.4),x,1.762,.128)); if(o.earrings) [-.128,.128].forEach(x=>add(body,G.ear,M(o.earrings,.2,1),x,1.68,.0)); }
  if(o.style!=="bald"){ const c=add(body,G.cap,hair,0,1.735,-.005,1.03,1.12,1.08); c.rotation.x=-.25; }
  if(o.style==="long") add(body,G.long,hair,0,1.6,-.1);
  if(o.style==="bun") add(body,G.bun,hair,0,1.86,-.08);
  if(o.style==="bob") add(body,G.long,hair,0,1.68,-.08,1.15,.6,1.2);
