  if(o.outfit==="blazer") { add(body,G.shirtV,M(o.inner||0xe8e4dc,.7),0,1.36,.128); add(body,G.lapel,top,-.07,1.36,.13); add(body,G.lapel,top,.07,1.36,.13); }
  if(o.outfit==="caterer") add(body,new THREE.BoxGeometry(.32,.6,.012),M(0x151515,.8),0,1.0,.135);
  if(o.outfit==="vest") add(body,new THREE.BoxGeometry(.36,.4,.02),M(0x3d4a3a,.9),0,1.3,.13);
  if(o.outfit==="security"){ add(body,new THREE.BoxGeometry(.2,.035,.03),M(0x050505,.1,.5),0,1.75,.13); }
