  if(o.badge){ const col={guest:0x2f5fb0,vip:0xb08a3e,press:0xb3261e,staff:0x2e6b3a}[o.badge]; add(body,G.strap,M(col,.6),-.045,1.38,.135).rotation.z=.25; add(body,G.strap,M(col,.6),.045,1.38,.135).rotation.z=-.25; add(body,G.card,M(0xf8f8f4,.5),0,1.22,.142); add(body,new THREE.BoxGeometry(.075,.025,.013),M(col,.5),0,1.26,.143); }
