  if(o.prop==="camera"){ hold=armR; armR.add(mesh(new THREE.BoxGeometry(.14,.1,.08),M(0x111111,.4,.3),0,-.6,.05)); const lens=mesh(new THREE.CylinderGeometry(.035,.035,.08,12),M(0x222222,.3,.4),0,-.6,.11); lens.rotation.x=Math.PI/2; armR.add(lens); }
  if(o.prop==="notepad"){ hold=armL; armL.add(mesh(new THREE.BoxGeometry(.1,.14,.015),M(0xf4f0e0,.8),0,-.6,.05)); }
  if(o.prop==="glass"){ hold=armR; armR.add(mesh(new THREE.CylinderGeometry(.03,.012,.15,10),M(0xffe7a8,.05,0,{transparent:true,opacity:.75}),0,-.62,.04,false)); }
  if(hold) hold.rotation.x=-1.0;
