const npcs=[], hitMeshes=[];
function randPoint(){ for(let i=0;i<40;i++){ const p=new THREE.Vector3(rand(-17,17),0,rand(-9.5,13)); if(p.length()<3.2) continue; let ok=true; for(const o of obstacles) if(p.x>o.x0-.7&&p.x<o.x1+.7&&p.z>o.z0-.7&&p.z<o.z1+.7){ok=false;break;} if(ok) return p; } return new THREE.Vector3(0,0,8); }
function spawnNPC(kind, opts){
  opts=opts||{};
  const roleKey = opts.role || (kind==="charmer" && Math.random()<.75 ? pick(["model","ambassador","socialite","investor"]) : wpick(ROLES));
  const cw = !opts.static && Math.random() < (["caterer","engineer"].includes(roleKey)?.18:.32);
  const look = cw ? chineseWoman(roleKey) : outfitFor(roleKey);
  const p=person(look);
  const n={kind,roleKey,role:ROLES[roleKey]?ROLES[roleKey].title:opts.title,name:cw?pick(CN_L)+" "+pick(CN_F):pick(FIRST)+" "+pick(LAST),...p,
    state:"wander",target:randPoint(),t:0,wanderFor:rand(6,14),speed:rand(1.2,1.6),walk:Math.random()*10,
    revealed:false,tag:null,steal:0,bar:null,talked:0,cooldown:rand(3,8),stuck:0,lastPos:new THREE.Vector3(),
    affil: kind==="guest"?null:wpick(AFFIL)};
  n.line = kind==="guest" ? pick((REAL_LINES[roleKey]||[]).concat(REAL_LINES._)) : pick((SPY_LINES[roleKey]||[]).concat(SPY_LINES._));
  if (kind==="charmer"||(kind==="guest"&&Math.random()<.3)) n.state="approach";
  if (opts.pos) n.g.position.copy(opts.pos); else { const d=pick(DOORS); n.g.position.set(d.x+Math.sign(-d.x)*.8,0,d.z+rand(-.6,.6)); }
  if (opts.static){ n.state="static"; n.g.rotation.y=opts.ry||0; }
  n.meshes.forEach(m=>{ m.userData.npc=n; hitMeshes.push(m); });
  scene.add(n.g); npcs.push(n); return n;
}
function removeNPC(n){ scene.remove(n.g); for(let i=hitMeshes.length-1;i>=0;i--) if(hitMeshes[i].userData.npc===n) hitMeshes.splice(i,1); const i=npcs.indexOf(n); if(i>=0) npcs.splice(i,1); }
