function reveal(n){ if(n.revealed) return; n.revealed=true; updContact(n); if(n.tag) n.g.remove(n.tag); n.tag = n.kind==="guest" ? tagSprite("Verified · "+n.role,"rgba(46,107,58,.92)") : tagSprite("Operative · "+AFFIL[n.affil].name,"rgba(179,38,30,.94)"); n.tag.scale.x = n.kind==="guest"?1.8:2.6; n.g.add(n.tag); }
